class Solution:
    def twoSum(self, nums, target, idx):
        target -= nums[idx]
        l, r = idx + 1, len(nums) - 1
        count = 0

        while l < r:
            total = nums[l] + nums[r]

            if total < target:
                count += r - l
                l += 1 
            else:
                r -= 1

        return count

    def threeSumSmaller(self, nums: list[int], target: int) -> int:
        nums.sort()
        n = len(nums)

        ans = 0 
        for i in range(n):
            ans += self.twoSum(nums, target, i)

        return ans
